<?php
namespace Tests\Feature\Sifi;
use App\Models\{User,SifiMonitoringObject,SifiIssueCandidate};
use App\Services\Sifi\{ResearchRetrievalWorkspace,FixtureResearchProvider,SourceObservationPipeline};
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{DB,Http};
use Illuminate\Support\Str;
use Inertia\Testing\AssertableInertia as Assert;
use Tests\TestCase;

final class ResearchBridgeTest extends TestCase
{
 use RefreshDatabase;
 private User $u;private SifiMonitoringObject $o;private object $session;
 protected function setUp():void{parent::setUp();$this->withoutVite();Http::preventStrayRequests();$this->u=User::factory()->create(['email_verified_at'=>now()]);$this->actingAs($this->u);$this->o=SifiMonitoringObject::create(['id'=>(string)Str::uuid(),'user_id'=>$this->u->id,'name'=>'[SYNTHETIC] Kendaraan listrik','description'=>'Objek uji research bridge sintetis','category'=>'Industri','aliases_json'=>['EV'],'keywords_json'=>['baterai'],'exclusions_json'=>['lowongan'],'geography'=>null,'objective'=>'Menelaah perkembangan baterai','horizon'=>'90 hari','state'=>'CONFIGURED','revision'=>1]);$this->post('/sifi/monitoring-objects/'.$this->o->id.'/research',['question'=>'Menelusuri baterai kendaraan listrik','object_revision'=>1,'query_limit'=>3,'result_limit'=>5])->assertSessionHasNoErrors();$this->session=DB::table('sifi_research_sessions')->first();}
 private function url():string{return '/sifi/monitoring-objects/'.$this->o->id.'/research-bridge';}
 private function decision():object{$envelope=app(ResearchRetrievalWorkspace::class)->search($this->u,$this->o,$this->session->id);$this->post($this->url(),['session_id'=>$this->session->id,'object_revision'=>1,'result_key'=>$envelope['results'][0]['key'],'query_sha256'=>$envelope['query_sha256']])->assertSessionHasNoErrors();return DB::table('sifi_research_retrievals')->first();}
 private function snapshot():object{$r=$this->decision();$this->post($this->url().'/'.$r->id.'/snapshot',['object_revision'=>1,'revision'=>1,'confirm_fixture'=>true])->assertSessionHasNoErrors();return DB::table('sifi_research_retrievals')->first();}
 private function import(object $r){return $this->post($this->url().'/'.$r->id.'/draft',['object_revision'=>1,'revision'=>$r->revision,'confirm_fixture'=>true,'analyst_note'=>'Catatan otomatis sintetis, bukan temuan aktual atau review manusia.']);}

 public function test_search_has_metadata_only_no_snapshot_or_domain_writes():void{$this->get($this->url())->assertOk()->assertInertia(fn(Assert $p)=>$p->where('search.network_requests',0)->where('search.documents_retrieved',0)->where('search.provider','LOCAL_SYNTHETIC_HTTP_FAKE'));$this->assertDatabaseCount('sifi_research_retrievals',0);$this->assertDatabaseCount('sifi_issue_candidates',0);Http::assertNothingSent();}
 public function test_explicit_decision_snapshot_and_pipeline_are_separate():void{$r=$this->decision();$this->assertNull($r->document_json);$this->assertDatabaseCount('sifi_evidence_drafts',0);$this->post($this->url().'/'.$r->id.'/snapshot',['object_revision'=>1,'revision'=>1,'confirm_fixture'=>true])->assertSessionHasNoErrors();$r=DB::table('sifi_research_retrievals')->first();$doc=json_decode($r->document_json,true);$q=$doc['quote'];$this->assertSame(hash('sha256',$doc['body']),$doc['body_sha256']);$this->assertSame($q['text'],substr($doc['body'],$q['byte_start'],$q['byte_end']-$q['byte_start']));$this->assertNull($doc['retrieved_at']);$this->import($r)->assertSessionHasNoErrors();$c=SifiIssueCandidate::firstOrFail();$this->assertSame('DRAFT',$c->review_state);$lineage=app(SourceObservationPipeline::class)->lineage($c);$this->assertSame($doc['body_sha256'],$lineage['packet_hash']);$this->assertSame($this->o->id,$lineage['records'][0]['observation']['provenance']['object_id']);$this->get('/sifi/issue-candidates/'.$c->id.'/executive-brief')->assertOk();$this->assertDatabaseMissing('sifi_claim_drafts',['verification_state'=>'VERIFIED']);$this->assertDatabaseCount('jobs',0);Http::assertNothingSent();}
 public function test_decision_dedup_and_revision_replay_preserve_single_candidate():void{$r=$this->snapshot();$this->import($r)->assertSessionHasNoErrors();$this->import($r)->assertSessionHasErrors('research');$this->assertDatabaseCount('sifi_issue_candidates',1);$this->assertDatabaseCount('sifi_research_retrieval_audit',3);}
 public function test_foreign_owner_cannot_access_search_decisions_snapshot_or_history():void{$r=$this->snapshot();$this->actingAs(User::factory()->create(['email_verified_at'=>now()]));$this->get($this->url())->assertForbidden();$this->post($this->url().'/'.$r->id.'/snapshot',['revision'=>2,'object_revision'=>1,'confirm_fixture'=>true])->assertForbidden();$this->import($r)->assertForbidden();$this->assertDatabaseCount('sifi_issue_candidates',0);}
 public function test_stale_object_and_expiry_block_import():void{$r=$this->snapshot();$this->o->update(['revision'=>2]);$this->import($r)->assertSessionHasErrors('research');$this->o->update(['revision'=>1]);$this->travel(31)->days();$this->import($r)->assertSessionHasErrors('research');$this->travelBack();$this->assertDatabaseCount('sifi_issue_candidates',0);}
 public function test_tamper_body_hash_and_span_never_create_drafts():void{$r=$this->snapshot();$doc=json_decode($r->document_json,true);$doc['quote']['byte_start']++;$raw=json_encode($doc,JSON_THROW_ON_ERROR);DB::table('sifi_research_retrievals')->where('id',$r->id)->update(['document_json'=>$raw,'document_sha256'=>hash('sha256',$raw)]);$this->import($r)->assertSessionHasErrors('research');$this->assertDatabaseCount('sifi_issue_candidates',0);}
 public function test_forged_input_and_missing_confirmation_fail_validation():void{$r=$this->decision();foreach(['url'=>'https://127.0.0.1/','grant'=>'forged','body'=>'injected','provider'=>'LIVE'] as $key=>$value)$this->post($this->url().'/'.$r->id.'/snapshot',['revision'=>1,'object_revision'=>1,'confirm_fixture'=>true,$key=>$value])->assertSessionHasErrors($key);$this->post($this->url().'/'.$r->id.'/snapshot',['revision'=>1,'object_revision'=>1,'confirm_fixture'=>false])->assertSessionHasErrors('confirm_fixture');$this->assertDatabaseCount('sifi_issue_candidates',0);}
 public function test_provider_contract_denies_schema_provenance_url_and_size():void{$provider=new FixtureResearchProvider();$context=['query_sha256'=>str_repeat('a',64),'entries'=>[]];foreach([['version'=>'bad'],['version'=>'ae14-search-1','provider'=>'LOCAL_SYNTHETIC_HTTP_FAKE','query_sha256'=>str_repeat('b',64),'state'=>'OK','results'=>[]]] as $bad){try{$provider->fromFixtureResponse($context,json_encode($bad));$this->fail('Accepted forged envelope');}catch(\Illuminate\Validation\ValidationException){$this->assertTrue(true);}}try{$provider->fromFixtureResponse($context,str_repeat('x',65537));$this->fail('Oversize');}catch(\Illuminate\Validation\ValidationException){$this->assertTrue(true);}$this->assertSame('QUOTA',$provider->fromFixtureResponse($context,'',429)['state']);$this->assertSame('UNAVAILABLE',$provider->fromFixtureResponse($context,'',500)['state']);Http::assertNothingSent();}
 public function test_nonempty_down_refuses_and_draft_transaction_rolls_back():void{$r=$this->snapshot();DB::listen(function($query){if(str_contains($query->sql,'insert into "sifi_foresight_drafts"'))throw new \RuntimeException('fixture failure');});try{app(ResearchRetrievalWorkspace::class)->import($this->u,$this->o,$r->id,['revision'=>2,'object_revision'=>1,'analyst_note'=>'Catatan sintetis otomatis untuk rollback.']);$this->fail('Expected failure');}catch(\RuntimeException $e){$this->assertSame('fixture failure',$e->getMessage());}$this->assertDatabaseCount('sifi_issue_candidates',0);$this->assertDatabaseHas('sifi_research_retrievals',['id'=>$r->id,'state'=>'FIXTURE_SNAPSHOT']);$m=require database_path('migrations/2026_10_27_000015_create_sifi_research_retrievals.php');$this->expectException(\RuntimeException::class);$m->down();}
 public function test_legacy_pipeline_route_cannot_bypass_stale_object_check():void{$r=$this->snapshot();$this->o->update(['revision'=>2]);$this->expectException(\Illuminate\Validation\ValidationException::class);app(SourceObservationPipeline::class)->createDraft($this->u,'research_fixture','Catatan sintetis untuk test bypass.',null,null,$r->id);}
 public function test_provider_denies_redirect_compression_private_urls_and_ambiguous_origins():void{$provider=new FixtureResearchProvider();$entries=json_decode($this->session->results_json,true)['entries'];$context=['query_sha256'=>str_repeat('a',64),'entries'=>$entries];$packet=['version'=>'ae14-search-1','provider'=>'LOCAL_SYNTHETIC_HTTP_FAKE','query_sha256'=>$context['query_sha256'],'state'=>'OK','results'=>$entries];$this->assertSame('UNAVAILABLE',$provider->fromFixtureResponse($context,'',302)['state']);foreach(['https://127.0.0.1/','https://169.254.169.254/','https://user:password@ev-api.sources.invalid/','https://ev-api.sources.invalid:8080/'] as $url){$bad=$packet;$bad['results'][0]['url']=$url;try{$provider->fromFixtureResponse($context,json_encode($bad));$this->fail('Unsafe URL');}catch(\Illuminate\Validation\ValidationException){$this->assertTrue(true);}}try{$provider->fromFixtureResponse($context,json_encode($packet),200,['Content-Encoding'=>'gzip']);$this->fail('Compression');}catch(\Illuminate\Validation\ValidationException){$this->assertTrue(true);}$bad=$packet;$bad['results']=[$entries[0],array_replace($entries[0],['origin'=>'other'])];try{$provider->fromFixtureResponse($context,json_encode($bad));$this->fail('Ambiguous origin');}catch(\Illuminate\Validation\ValidationException){$this->assertTrue(true);}}
}
